-- Additive, idempotent migration; existing experiments and profiles are preserved.
CREATE TABLE IF NOT EXISTS profile_rate_samples (RUN_AT_UTC_US INTEGER NOT NULL, EXPERIMENT_NAME TEXT NOT NULL, WT_PERCENT TEXT NOT NULL, PROFILE_TYPE TEXT NOT NULL, X REAL NOT NULL, RATE REAL NOT NULL, PRIMARY KEY(RUN_AT_UTC_US, EXPERIMENT_NAME, WT_PERCENT, PROFILE_TYPE, X));
